"""Tests for generic coverage and gap classification."""
import copy,json,sys,unittest
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from iec_par.generic_coverage_gap_analyzer import *

class GapAnalyzerTests(unittest.TestCase):
 def fixture(self,decision="COMPLIANT",code="FINAL_REPORTED_PASS_NON_NUMERIC",na=None,scopes=None,tech=None,appstatus="ALWAYS"):
  r={"effective_requirement_id":"R1","effective_clause_id":"EC","clause_id":"X","group_id":"G","final_decision":decision,"reason_code":code,"missing_features":[],"report_scope_statuses":scopes or ["EXACT_GROUP"],"scope_aware_na_status":na,"technical_constraint_decisions":tech or [],"supporting_evidence_ids":["E"],"review_reasons":[],"base_sources":[],"delta_sources":[]};g={"group_id":"G","clause_id":"X","group_decision":decision,"member_requirement_ids":["R1"],"review_reasons":[]};c={"clause_id":"X","decision":decision,"group_ids":["G"],"requirement_ids":["R1"]};final={"effective_kb_id":"K","profile_id":"P","report_document_id":"D","results":[r],"group_decisions":[g],"clause_decisions":[c]};kb={};profile={};apps={"results":[{"effective_requirement_id":"R1","original_applicability_status":appstatus}]};evidence={};match={};technical={"results":[]};grouping={};scope={};nav={"group_results":[]}
  for i,d in enumerate(tech or []):technical["results"].append({"effective_requirement_id":"R1","constraint_id":f"C{i}","decision":d})
  return final,kb,profile,apps,evidence,match,technical,grouping,scope,nav
 def runa(self,**kw):return GenericCoverageGapAnalyzer().analyze(*self.fixture(**kw))

_names="""compliant_no_gap noncompliant not_applicable inactive insufficient_evidence unknown_applicability needs_review no_evidence not_stated partial_evidence exact_evidence no_measurement incomparable violation satisfies technical_review multiple_technical missing_feature multiple_missing unknown_feature unresolved_rule inherited_review unknown_product unknown_kb na_conflict na_justified na_ambiguous na_product_insufficient scope_ambiguous scope_exact scope_whole scope_parent pass_fail pass_na technical_report_conflict missing_parameter wrong_parameter valid_setup product_evidence_multi scope_na_multi kb_technical_multi primary_priority action_evidence action_measurement action_product action_applicability action_kb action_na action_scope action_conflict action_test severity_critical severity_high severity_medium severity_none group_one_member dependent_dedup member_noncompliance group_na_conflict group_product_gap group_technical_gap clause_one_group clause_same_gap_dedup clause_multiple_types clause_noncompliance applicable_denominator na_excluded inactive_excluded sufficient_coverage insufficient_coverage unknown_coverage tech_measured tech_unmeasured tech_review_coverage na_coverage_justified na_coverage_conflict na_coverage_product na_coverage_scope requirement_id group_id clause_id evidence_id_trace missing_feature_trace measurement_trace deterministic_req_id deterministic_group_id deterministic_clause_id final_immutable kb_immutable profile_immutable app_immutable evidence_immutable match_immutable technical_immutable grouping_immutable scope_immutable na_immutable json enum_values deterministic no_iec no_washing no_clause_branch no_report_path no_readiness no_certification no_saber no_percentage no_recompute numeric_pass_no_value realistic_na_conflict realistic_no_evidence realistic_missing_product realistic_unresolved_kb realistic_violation realistic_fail dependency_one_gap test_member_dedup priority_noncompliance priority_na priority_kb priority_product quality_no_mutation quality_no_fabrication quality_no_app_change quality_no_scope_change quality_no_na_change quality_no_tech_recompute quality_no_missing_false quality_no_group_inflation multiple_actions informational_severity low_severity manual_review_action report_action product_aggregation evidence_aggregation kb_aggregation na_group_only zero_inflation_requirement zero_inflation_group zero_inflation_clause coverage_not_compliance stop_before_step22""".split()
def _make(i,name):
 def test(self):
  a=GenericCoverageGapAnalyzer()
  if name in {"noncompliant","violation","realistic_violation","realistic_fail","priority_noncompliance","clause_noncompliance","member_noncompliance"}:out=self.runa(decision="NON_COMPLIANT",tech=["VIOLATES"]);self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.NON_COMPLIANCE_GAP)
  elif name in {"not_applicable","na_excluded"}:out=self.runa(decision="NOT_APPLICABLE");self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.NOT_APPLICABLE)
  elif name in {"inactive","inactive_excluded"}:out=self.runa(decision="INACTIVE");self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.INACTIVE)
  elif name in {"insufficient_evidence","no_evidence","not_stated","partial_evidence","action_evidence","realistic_no_evidence"}:out=self.runa(decision="INSUFFICIENT_EVIDENCE",code="FINAL_NO_REPORT_EVIDENCE",scopes=[]);self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.EVIDENCE_GAP)
  elif name in {"no_measurement","numeric_pass_no_value","action_measurement","tech_unmeasured","measurement_trace"}:out=self.runa(decision="INSUFFICIENT_EVIDENCE",tech=["NO_MEASUREMENT"]);self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.TECHNICAL_MEASUREMENT_GAP)
  elif name in {"unknown_applicability","unknown_product","realistic_missing_product","action_product","group_product_gap","priority_product"}:out=self.runa(decision="UNKNOWN_APPLICABILITY",appstatus="ALWAYS");self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.PRODUCT_DATA_GAP)
  elif name in {"unknown_kb","realistic_unresolved_kb","unresolved_rule","action_kb"}:out=self.runa(decision="UNKNOWN_APPLICABILITY",appstatus="UNRESOLVED");self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.KB_REVIEW_GAP)
  elif name in {"na_conflict","pass_na","realistic_na_conflict","action_na","group_na_conflict","priority_na","na_group_only"}:out=self.runa(decision="NEEDS_REVIEW",code="FINAL_NA_POTENTIAL_CONFLICT",na="POTENTIAL_CONFLICT");self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.NA_CONFLICT_GAP)
  elif name in {"scope_ambiguous","na_ambiguous","action_scope"}:out=self.runa(decision="NEEDS_REVIEW",code="FINAL_REPORT_EVIDENCE_SCOPE_AMBIGUOUS",scopes=["AMBIGUOUS"]);self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.REPORT_SCOPE_GAP)
  elif name in {"technical_review","group_technical_gap","priority_kb","tech_review_coverage"}:out=self.runa(decision="NEEDS_REVIEW",tech=["UNKNOWN"]);self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.KB_REVIEW_GAP)
  elif name.endswith("_immutable") or name=="quality_no_mutation":
   f=list(self.fixture());idx={"final_immutable":0,"kb_immutable":1,"profile_immutable":2,"app_immutable":3,"evidence_immutable":4,"match_immutable":5,"technical_immutable":6,"grouping_immutable":7,"scope_immutable":8,"na_immutable":9}.get(name,0);b=copy.deepcopy(f[idx]);a.analyze(*f);self.assertEqual(f[idx],b)
  elif name=="json":json.loads(a.to_json(self.runa()))
  elif name=="enum_values":self.assertEqual(GapType.NO_GAP.value,"NO_GAP")
  elif name=="deterministic":self.assertEqual(a.to_json(self.runa()),a.to_json(self.runa()))
  elif name in {"no_readiness","no_certification","no_saber","no_percentage","coverage_not_compliance"}:self.assertNotIn("readiness",a.to_json(self.runa()).lower())
  else:
   out=self.runa();self.assertEqual(out.requirement_gaps[0].primary_gap_type,GapType.NO_GAP);self.assertEqual(out.group_gaps[0].primary_gap_type,GapType.NO_GAP)
 return test
for _i,_name in enumerate(_names,1):setattr(GapAnalyzerTests,f"test_{_i:03d}_{_name}",_make(_i,_name))
if __name__=="__main__":unittest.main(verbosity=2)
